export function programExamples(){return [{"file": "01-data-sort-merge.sas", "title": "DATA step, SORT and match MERGE", "description": "Self-contained generated data; no project folder required.", "code": "/* Self-contained example: generate, sort, match-merge and calculate. */\ndata demo_claims;\n    do id=1 to 12;\n        provider=mod(id,3)+1;\n        amount=id*125;\n        output;\n    end;\nrun;\ndata demo_providers;\n    do provider=1 to 3;\n        rate=provider*0.05;\n        output;\n    end;\nrun;\nproc sort data=demo_claims; by provider; run;\nproc sort data=demo_providers; by provider; run;\ndata demo_merged;\n    merge demo_claims(in=a) demo_providers(in=b);\n    by provider;\n    if a;\n    adjusted=amount*(1-rate);\n    matched=b;\nrun;\n"}, {"file": "02-uniform-random.sas", "title": "Uniform random numbers (MT32)", "description": "Self-contained, explicit seed 12345, two uniform columns and HEX output.", "code": "/* Explicit MT32 seed. Seed 12345 uniform draws have a real SAS comparison fixture. */\ndata demo_uniform;\n    call streaminit('MT32',12345);\n    do id=1 to 1000;\n        uniform_x=rand('uniform');\n        uniform_y=rand('uniform');\n        x_hex=put(uniform_x,hex16.);\n        output;\n    end;\nrun;\n"}, {"file": "03-charts.sas", "title": "Charts: scatter, bars, histogram and pie", "description": "Self-contained; renders all five supported chart types.", "code": "/* Standalone chart demo: no folder or CSV import is required. */\ndata chart_sample;\n  length category $ 6;\n  do id = 1 to 120;\n    x = id;\n    y = sqrt(id) + mod(id, 7);\n    amount = 10 + mod(id, 17);\n    if mod(id, 3) = 0 then category = 'Alpha';\n    else if mod(id, 3) = 1 then category = 'Beta';\n    else category = 'Gamma';\n    output;\n  end;\nrun;\ntitle 'Values by category';\nproc sgplot data=chart_sample;\n  scatter x=x y=y / group=category;\n  xaxis label='Observation';\n  yaxis label='Calculated value';\nrun;\ntitle 'Total amount by category';\nproc sgplot data=chart_sample;\n  hbar category / response=amount stat=sum;\nrun;\ntitle 'Mean amount by category';\nproc sgplot data=chart_sample;\n  vbar category / response=amount stat=mean;\nrun;\ntitle 'Distribution of calculated values';\nproc sgplot data=chart_sample;\n  histogram y / nbins=12 scale=count;\nrun;\ntitle 'Share of total amount';\nproc sgpie data=chart_sample;\n  pie category / response=amount stat=sum;\nrun;\ntitle;\n"}, {"file": "04-means.sas", "title": "PROC MEANS: totals, subtotals and NWAY", "description": "Self-contained; inspect demo_all_types, demo_nway and demo_default_stats.", "code": "/* All CLASS types: total, each one-way subtotal, and complete combinations.\n   _TYPE_: 0=overall, 1=period, 2=site, 3=site+period.\n   Missing CLASS rows are excluded from ALL types unless MISSING is specified. */\ndata demo_observations;\n    length site $ 8;\n    do id=1 to 24;\n        if mod(id,2)=0 then site='North'; else site='South';\n        period=mod(id,3)+1;\n        amount=100+id*7;\n        if mod(id,5)=0 then amount=.;\n        output;\n    end;\nrun;\nproc means data=demo_observations n nmiss mean std var min max;\n    class site period;\n    var amount;\n    output out=demo_all_types n= nmiss= mean= std= var= / autoname;\nrun;\n/* NWAY removes the overall and partial-group rows from the saved dataset. */\nproc means data=demo_observations nway noprint;\n    class site period;\n    var amount;\n    output out=demo_nway mean=mean_amount;\nrun;\n/* With no statistic requests on OUTPUT, SAS stores five _STAT_ rows per level. */\nproc means data=demo_observations noprint;\n    var amount;\n    output out=demo_default_stats;\nrun;\n"}, {"file": "05-macros.sas", "title": "Macro-generated DATA step", "description": "Self-contained macro with a keyword argument; inspect Expanded code.", "code": "/* Macros generate SAS statements; Expanded code shows the result. */\n%macro squares(limit=10);\n    data demo_squares;\n        do number=1 to &limit;\n            square=number**2;\n            output;\n        end;\n    run;\n%mend squares;\n%squares(limit=20);\n"}, {"file": "06-project-csv.sas", "title": "Project CSV import and export", "description": "Choose the included demo-project folder first. Reads claims.csv and writes reviewed.csv.", "code": "/* Choose the demo-project folder before running this program.\n   The input and output paths are relative to that selected folder. */\nfilename source 'claims.csv';\nproc import datafile=source out=claims dbms=csv replace;\n  getnames=yes;\n  guessingrows=max;\nrun;\n\ndata reviewed;\n  set claims;\n  if paid_amount > 1000;\n  excess = paid_amount - allowed_amount;\n  format paid_amount dollar12.2 excess dollar12.2;\n  keep claim_id provider paid_amount excess;\nrun;\n\n/* REPLACE explicitly allows overwriting the result from a previous run. */\nproc export data=reviewed outfile='reviewed.csv' dbms=csv replace;\nrun;\n"}, {"file": "07-json-libraries.sas", "title": "Permanent JSON libraries", "description": "Choose the included demo-project folder first, with its existing tables subfolder.", "code": "/* Select demo-project, then run. The existing tables folder holds native tables. */\nlibname saved 'tables';\nproc import datafile='claims.csv' out=claims dbms=csv replace;\n  getnames=yes;\n  guessingrows=max;\nrun;\ndata saved.reviewed;\n  set claims;\n  if paid_amount > 1000;\n  excess = paid_amount - allowed_amount;\n  format paid_amount dollar12.2 allowed_amount dollar12.2 excess dollar12.2 service_date date9.;\nrun;\n/* This SET works in a later run too. Reissue LIBNAME after reopening the app. */\ndata restored;\n  set saved.reviewed;\nrun;\n"}, {"file": "08-formats.sas", "title": "INPUT, PUT and formats", "description": "Self-contained numeric/date conversion and display formats.", "code": "data demo_formats;\n    amount=input('$1,234.50',comma12.);\n    sas_day=input('03/15/2018',mmddyy10.);\n    iso_day=put(sas_day,e8601da10.);\n    padded_id=put(1350,z8.);\n    format amount dollar12.2 sas_day date9.;\nrun;\n"}];}
